"use client"

import * as React from "react"
import { motion } from "framer-motion"
import { cn } from "@/lib/utils"

interface GlassSkeletonProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: "default" | "circular" | "text" | "card"
  width?: string | number
  height?: string | number
  lines?: number
}

const GlassSkeleton = React.forwardRef<HTMLDivElement, GlassSkeletonProps>(
  ({ className, variant = "default", width, height, lines = 1, ...props }, ref) => {
    const baseClasses = cn(
      "relative overflow-hidden",
      "bg-white/5 backdrop-blur-sm",
      "before:absolute before:inset-0",
      "before:bg-gradient-to-r before:from-transparent before:via-white/10 before:to-transparent",
      "before:animate-[shimmer_2s_infinite]",
    )

    const variantClasses = {
      default: "rounded-xl",
      circular: "rounded-full",
      text: "rounded-md h-4",
      card: "rounded-2xl min-h-[120px]",
    }

    if (variant === "text" && lines > 1) {
      return (
        <div className="space-y-2" ref={ref} {...props}>
          {Array.from({ length: lines }).map((_, index) => (
            <motion.div
              key={index}
              className={cn(baseClasses, variantClasses.text, index === lines - 1 && "w-3/4", className)}
              style={{
                width: index === lines - 1 ? "75%" : width,
                height,
                backgroundSize: "400% 100%",
              }}
              animate={{
                backgroundPosition: ["200% 0", "-200% 0"],
              }}
              transition={{
                duration: 2,
                repeat: Number.POSITIVE_INFINITY,
                ease: "linear",
                delay: index * 0.1,
              }}
              aria-hidden="true"
            />
          ))}
        </div>
      )
    }

    return (
      <motion.div
        ref={ref}
        className={cn(baseClasses, variantClasses[variant], className)}
        // Ensure onDrag prop is not forwarded to motion.div
        {...(() => {
          const { onDrag, ...rest } = props as any // eslint-disable-line @typescript-eslint/no-explicit-any
          return rest
        })()}
        style={{
          width,
          height,
          backgroundSize: "400% 100%",
        }}
        animate={{
          backgroundPosition: ["200% 0", "-200% 0"],
        }}
        transition={{
          duration: 2,
          repeat: Number.POSITIVE_INFINITY,
          ease: "linear",
        }}
        aria-hidden="true"
        role="status"
        aria-label="Loading..."
        {...props}
      />
    )
  },
)
GlassSkeleton.displayName = "GlassSkeleton"

export { GlassSkeleton }

"use client"

import type * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

const glassBadgeVariants = cva(
  cn(
    "inline-flex items-center rounded-full px-3 py-1 text-xs font-medium",
    "backdrop-blur-xl border transition-all duration-300",
  ),
  {
    variants: {
      variant: {
        default: "bg-white/15 border-white/25 text-white",
        primary: cn("bg-linear-to-r from-cyan-500/30 to-blue-500/30", "border-cyan-400/30 text-cyan-100"),
        success: cn("bg-emerald-500/20 border-emerald-400/30 text-emerald-100"),
        warning: cn("bg-amber-500/20 border-amber-400/30 text-amber-100"),
        destructive: cn("bg-red-500/20 border-red-400/30 text-red-100"),
        outline: "bg-transparent border-white/30 text-white/80",
      },
      size: {
        sm: "px-2 py-0.5 text-xs",
        md: "px-3 py-1 text-sm",
        lg: "px-4 py-2 text-base",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "md",
    },
  },
)

export interface GlassBadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof glassBadgeVariants> {}

function GlassBadge({ className, variant, ...props }: GlassBadgeProps) {
  return <div className={cn(glassBadgeVariants({ variant }), className)} {...props} />
}

export { GlassBadge, glassBadgeVariants }

